def url_decode(s):
    out = []
    i = 0
    hexd = '0123456789abcdefABCDEF'
    while i < len(s):
        ch = s[i]
        if ch == '+':
            out.append(' ')
            i += 1
        elif ch == '%':
            if i + 2 >= len(s) or s[i+1] not in hexd or s[i+2] not in hexd:
                raise ValueError('bad escape')
            out.append(chr(int(s[i+1:i+3], 16)))
            i += 3
        else:
            out.append(ch)
            i += 1
    return ''.join(out)

def brace_expand(s):
    parts = []
    i = 0
    while i < len(s):
        if s[i] == '{':
            j = s.index('}', i)
            opts = s[i+1:j].split(',')
            if len(opts) == 1:
                parts.append(['{' + opts[0] + '}'])
            else:
                parts.append(opts)
            i = j + 1
        else:
            j = i
            while j < len(s) and s[j] != '{':
                j += 1
            parts.append([s[i:j]])
            i = j
    out = ['']
