def zigzag(s, rows):
    if rows == 1 or rows >= len(s):
        return s
    out = [''] * rows
    r, step = 0, 1
    for c in s:
        out[r] += c
        if r == 0:
            step = 1
        elif r == rows - 1:
            step = -1
        r += step
    return ''.join(out)
